 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [[0] * w for _ in range(h)]
    colors = {v for row in grid for v in row if v}
    # Tile each colored motif in the row band occupied by the shortest motif,
    # aligning all motifs by their topmost row and preserving x positions.
    tops = {color: min(r for r in range(h) for c in range(w) if grid[r][c] == color) for color in colors}
    base = max(tops.values())
    for color in colors:
        cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        top = tops[color]
        shift = base - top
        for r, c in cells:
            nr = r + shift
            if 0 <= nr < h:
                out[nr][c] = color
    return out
